// Encrypt the data with the key using AES and GCM mode.
// The provided key bytes is long enough (>= 16 bytes). Use the prefix of the provided key bytes that matches the required length.
// Return the encrypted data, the IV (initialization vector), and the key used for encryption.
//
// Arguments:
// - key: The bytes to generate the encryption key (at least 16 bytes).
// - data: The data to encrypt.
//
// Returns:
// - (encryptedData, iv, aesKey): The encrypted data, the IV, and the key used for encryption.
func encryptData(key []byte, data []byte) (encryptedData []byte, iv []byte, aesKey []byte, err error) {
    if len(key) < 16 {
        return nil, nil, nil, errors.New("key must be at least 16 bytes long")
    }

    // Use the first 16 bytes of the key for AES-128
    aesKey = key[:16]

    // Create a new AES cipher
    block, err := aes.NewCipher(aesKey)
    if err != nil {
        return nil, nil, nil, err
    }

    // Generate a new IV
    iv = make([]byte, aes.BlockSize)
    if _, err := io.ReadFull(rand.Reader, iv); err != nil {
        return nil, nil, nil, err
    }

    // Create GCM (Galois/Counter Mode) cipher
    gcm, err := cipher.NewGCM(block)
    if err != nil {
        return nil, nil, nil, err
    }

    // Encrypt the data
    encryptedData = gcm.Seal(nil, iv, data, nil)

    return encryptedData, iv, aesKey, nil
}
